package main

import (
	"bytes"
	"go/format"
	"log"
	"os"
	"text/template"
)

var src = template.Must(template.New("enum").Parse(`// Code generated by gen; DO NOT EDIT.
package {{.Pkg}}

const (
{{range .Values}}	{{.}} = "{{.}}"
{{end}})
`))

func main() {
	var buf bytes.Buffer
	if err := src.Execute(&buf, map[string]any{"Pkg": "colors", "Values": []string{"Red", "Green"}}); err != nil {
		log.Fatal(err)
	}
	out, err := format.Source(buf.Bytes())
	if err != nil {
		log.Fatal(err)
	}
	f, err := os.Create("colors_gen.go")
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()
	f.Write(out)
	tmpl := template.Must(template.ParseGlob("tools/gen/*.tmpl"))
	_ = tmpl.Execute(os.Stdout, nil)
}
